class Main {
    public static void main(String[] args) {
        // 약수를 셀 정수예요.
        int n = 12;
        // 찾은 약수의 개수예요.
        int count = 0;
        // 1부터 n까지 하나씩 확인해요.
        for (int i = 1; i <= n; i++) {
            // i가 n의 약수인지 확인해요.
            if (i % n == 0) {
                count++;
            }
        }
        System.out.println(n + "의 약수: " + count + "개");
    }
}
